-- PostgreSQL 15+; synthetic metadata only.
CREATE SCHEMA IF NOT EXISTS agriculture_demo;
CREATE TABLE IF NOT EXISTS agriculture_demo.service_areas(area_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,area_code TEXT NOT NULL UNIQUE,area_label TEXT NOT NULL,area_level TEXT NOT NULL CHECK(area_level IN('district','subcounty','parish','service_zone')),is_active BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE IF NOT EXISTS agriculture_demo.farm_refs(farm_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,farm_token TEXT NOT NULL UNIQUE,area_id BIGINT NOT NULL REFERENCES agriculture_demo.service_areas(area_id) ON DELETE RESTRICT,primary_crop TEXT NOT NULL,season_code TEXT NOT NULL,is_active BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE IF NOT EXISTS agriculture_demo.extension_visits(visit_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,visit_ref TEXT NOT NULL UNIQUE,farm_id BIGINT NOT NULL REFERENCES agriculture_demo.farm_refs(farm_id) ON DELETE RESTRICT,visit_at TIMESTAMPTZ NOT NULL,officer_ref TEXT NOT NULL,topic TEXT NOT NULL CHECK(topic IN('crop_health','soil_management','water_management','post_harvest','market_access','other')),outcome TEXT NOT NULL CHECK(outcome IN('scheduled','completed','follow_up','cancelled')),finding_summary TEXT NOT NULL,follow_up_due DATE);
CREATE TABLE IF NOT EXISTS agriculture_demo.input_deliveries(delivery_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,delivery_ref TEXT NOT NULL UNIQUE,farm_id BIGINT NOT NULL REFERENCES agriculture_demo.farm_refs(farm_id) ON DELETE RESTRICT,input_type TEXT NOT NULL CHECK(input_type IN('seed','fertiliser','tool','feed','other')),input_label TEXT NOT NULL,planned_qty NUMERIC(12,3) NOT NULL CHECK(planned_qty>0),dispatched_qty NUMERIC(12,3) NOT NULL DEFAULT 0 CHECK(dispatched_qty>=0 AND dispatched_qty<=planned_qty),received_qty NUMERIC(12,3) NOT NULL DEFAULT 0 CHECK(received_qty>=0 AND received_qty<=dispatched_qty),unit_code TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'planned' CHECK(status IN('planned','dispatched','received','disputed','cancelled')),dispatch_ref TEXT,receipt_ref TEXT,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS agriculture_demo.delivery_events(event_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,delivery_id BIGINT NOT NULL REFERENCES agriculture_demo.input_deliveries(delivery_id) ON DELETE RESTRICT,previous_status TEXT,new_status TEXT NOT NULL CHECK(new_status IN('planned','dispatched','received','disputed','cancelled')),event_note TEXT NOT NULL,actor_ref TEXT NOT NULL,happened_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS ix_agri_farms_area ON agriculture_demo.farm_refs(area_id,primary_crop) WHERE is_active;
CREATE INDEX IF NOT EXISTS ix_agri_visits_followup ON agriculture_demo.extension_visits(outcome,follow_up_due);
CREATE INDEX IF NOT EXISTS ix_agri_delivery_status ON agriculture_demo.input_deliveries(status,created_at DESC);
CREATE INDEX IF NOT EXISTS ix_agri_event_history ON agriculture_demo.delivery_events(delivery_id,happened_at DESC,event_id DESC);